'use strict';
const parties={Ap:{name:'Arbeiderpartiet',color:'#ef6a72',logo:'ap.png'},H:{name:'Høyre',color:'#2678be',logo:'hoyre.png'},Sp:{name:'Senterpartiet',color:'#299755',logo:'sp-symbol.png'},FrP:{name:'Fremskrittspartiet',color:'#253c73',logo:'frp.png'},KrF:{name:'Kristelig Folkeparti',color:'#e9ae22',logo:'krf.png'},V:{name:'Venstre',color:'#007d82',logo:'v-symbol.svg'},SV:{name:'Sosialistisk Venstreparti',color:'#d94b63',logo:'sv.png'},R:{name:'Rødt',color:'#7f1724',logo:'r.svg'},MDG:{name:'Miljøpartiet De Grønne',color:'#63932d',logo:'mdg.svg'},SOL:{name:'Solrenningslista',color:'#766286'},Andre:{name:'Andre',color:'#8993a3'}};
const mayorPartyNames={
 '5632':'Båtsfjordlista','5512':'Tverrpolitisk liste','1859':'Distriktsliste','5612':'Flyttsamelista',
 '3403':'BBL','1517':'Folkelista','5616':'Sammen for Sørøya','1144':'Bygdeliste','3434':'Bygdeliste',
 '5536':'Folkelista','4629':'Solrenningslista','1874':'Moskenes Fellesliste','5618':'Bygdelista Måsøy',
 '5044':'Bygdeliste','5020':'Bygdeliste','5043':'Samarbeidslista','1836':'Fellesliste Ap/KrF',
 '1856':'Samarbeidslista','1812':'Tverrpolitisk liste','5636':'FTSSH','1151':'Utsiralista',
 '3454':'Tverrpolitisk','3435':'Bygdeliste','1857':'Værøylista'
};
const partyLabel=m=>mayorPartyNames[m.id]||({Ap:'Arbeiderpartiet',H:'Høyre',Sp:'Senterpartiet',FrP:'Frp',KrF:'KrF',V:'Venstre',SV:'SV',R:'Rødt',MDG:'MDG'}[m.party]||m.party||'Andre');
const partyTooltip=m=>['Ap','H','Sp','FrP','KrF','V','SV','R','MDG'].includes(m.party)?'':` (${esc(partyLabel(m))})`;
const electionLabels={'Industri- og Næringspartiet':'INP','Norgesdemokratene':'ND','Konservativt':'K','Kystpartiet':'Kp','Folkets Parti':'FP','Liberalistene':'L','Pensjonistpartiet':'Pp'};
const electionPartyMeta={'Rødt':parties.R,'Arbeiderpartiet':parties.Ap,'Høyre':parties.H,'Fremskrittspartiet':parties.FrP,'Sosialistisk Venstreparti':parties.SV,'Senterpartiet':parties.Sp,'Kristelig Folkeparti':parties.KrF,'Venstre':parties.V,'Miljøpartiet De Grønne':parties.MDG,'Industri- og Næringspartiet':{color:'#e87916'},'Konservativt':{color:'#183b70'}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=n=>n.toLocaleString('nb-NO',{minimumFractionDigits:1,maximumFractionDigits:1});
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('nb-NO',{day:'numeric',month:'long',year:'numeric'});
const logo=(p,party='')=>p.logo?`<img class="party-logo ${party==='H'?'party-h':''}" src="assets/logos/${p.logo}" alt="${esc(p.name)}">`:p.name==='Andre'?'<span class="local" aria-label="Andre">A</span>':'<span class="local" aria-label="Solrenningslista">SOL</span>';

const bergenCandidates=[
 {party:'H',label:'Høyre',acronym:'H',name:'Chris Jørgen Knudsen Rødland',status:'Valgt byrådslederkandidat · nr. 1 i listeinnstillingen',image:'assets/candidates/chris-rodland.jpg',credit:'Foto: Andrew M. S. Buller',source:'https://hoyre.no/bergen/aktuelt/komiteens-innstilling-er-klar/'},
 {party:'Ap',label:'Arbeiderpartiet',acronym:'Ap',name:'Toppkandidat ikke valgt ennå'},
 {party:'FrP',label:'Frp',acronym:'FrP',name:'Toppkandidat ikke valgt ennå',status:'Nominasjon pågår',source:'https://www.frp.no/nyheter/lokalt/bergen-frps-valgliste-2027-2031'},
 {party:'SV',label:'SV',acronym:'SV',name:'Toppkandidat ikke valgt ennå',status:'Nominasjonsmøte planlagt i januar',source:'https://bergen.sv.no/lokalvalget-2027/'},
 {party:'MDG',label:'MDG',acronym:'MDG',name:'Katrine Nødtvedt',status:'Innstilt som førstekandidat',image:'assets/candidates/katrine-nodtvedt.jpg',source:'https://bergen.mdg.no/nyhet/innstillingen-til-nominasjonsmotet-er-klar/'},
 {party:'BL',label:'Bergenslisten',acronym:'BL',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'},
 {party:'V',label:'Venstre',acronym:'V',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'},
 {party:'R',label:'Rødt',acronym:'R',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'},
 {party:'Sp',label:'Senterpartiet',acronym:'Sp',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'},
 {party:'KrF',label:'KrF',acronym:'KrF',name:'Per Erik Gåskjenn',status:'Innstilt',image:'assets/candidates/per-erik-gaskjenn.jpg'},
 {party:'PP',label:'Pensjonistpartiet',acronym:'PP',name:'Toppkandidat ikke valgt ennå',status:'Ikke offentlig avklart'}
];

const priorityCandidateIds=['0301','4601','5001','1103','3201','4204','3301','3203','3205','3107','1108','5501','3907','3207','3105','3905','1508','4003','1804','3103','3222','3909','3118','4203','3209','1149','4626','1106','4001','3411'];
const candidatePartyTemplates=[['Ap','Arbeiderpartiet','Ap'],['H','Høyre','H'],['FrP','Frp','FrP'],['SV','SV','SV'],['Sp','Senterpartiet','Sp'],['KrF','KrF','KrF'],['V','Venstre','V'],['MDG','MDG','MDG'],['R','Rødt','R']];
const priorityCandidates=Object.fromEntries(priorityCandidateIds.map(id=>[id,candidatePartyTemplates.map(([party,label,acronym])=>({party,label,acronym,name:'Toppkandidat ikke lagt inn ennå'}))]));
priorityCandidates['4601']=bergenCandidates;
priorityCandidates['1108'][5]={party:'KrF',label:'KrF',acronym:'KrF',name:'Olav Eggebø Ånonsen',status:'Innstilt',image:'assets/candidates/olav-eggebo-aanonsen.jpg'};

function renderCandidates(m){
 const host=document.querySelector('#candidate-grid');
 const candidates=priorityCandidates[m.id];const section=document.querySelector('#bergen-candidates');if(!candidates){host.innerHTML='';section.hidden=true;return}section.hidden=false;section.querySelector('.candidate-kicker').textContent=m.name;section.querySelector('h2').textContent='Toppkandidater 2027';host.innerHTML=candidates.map(c=>{const p=parties[c.party]||{name:c.label,color:c.party==='BL'?'#e77e23':c.party==='PP'?'#555d69':'#526779'};const mark=p.logo?`<span class="candidate-logo">${logo(p,c.party)}</span>`:`<span class="candidate-logo candidate-wordmark" style="--party:${p.color}">${esc(c.acronym)}</span>`;return `<article class="candidate-card" style="--party:${p.color}"${c.status?` title="${esc(c.status)}"`:""}><div class="candidate-card-top">${mark}<span class="candidate-party">${esc(c.label)}</span></div>${c.image?`<div class="candidate-photo-wrap"><img class="candidate-photo" src="${c.image}" alt="${esc(c.name)}"${c.credit?` title="${esc(c.credit)}"`:""} loading="lazy">${c.status==='Innstilt'?'<span class="candidate-status">Innstilt</span>':''}</div>`:`<div class="candidate-placeholder" aria-hidden="true"><span class="placeholder-mark">${esc(c.acronym)}</span><span>${c.name==='Katrine Nødtvedt'?'Bilde kommer':'Kandidat ikke valgt'}</span></div>`}<div class="candidate-copy"><h3>${esc(c.name)}</h3>${c.credit?`<small>${esc(c.credit)}</small>`:''}</div></article>`}).join('');
}

function renderElection(result){
 if(!result)return '<section class="election-2023"><p>Valgresultatet kunne ikke lastes.</p></section>';
 const maxPercent=Math.max(...result.results.map(r=>r.percent),1);
 const rows=result.results.filter(r=>r.percent>0||r.seats>0).sort((a,b)=>b.percent-a.percent).map(r=>{
  const p=parties[r.party]||electionPartyMeta[r.party]||parties.Andre,label=electionLabels[r.party]||({H:'Høyre',V:'Venstre',R:'Rødt'}[r.party]||r.party);
  return `<div class="bar-row" aria-label="${esc(label)}: ${pct(r.percent)} prosent, ${r.seats} mandater"><span class="bar-label">${esc(label)}</span><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="--party:${p.color};--value:${r.percent/maxPercent*100}%"></div></div><span class="bar-value">${pct(r.percent)}</span><span class="bar-seats">${r.seats}</span></div>`;
 }).join('');
 return `<section class="election-2023" aria-labelledby="election-heading"><h3 id="election-heading">Valgresultat 2023</h3><p class="visually-hidden">Valgresultat 2023 i ${esc(result.name)}: oppslutning og mandater per parti</p><div class="poll-table-head" aria-hidden="true"><span>Parti</span><span></span><span>Prosent</span><span>Mandater</span></div><div class="chart election-chart" role="group" aria-label="Valgresultat 2023 i ${esc(result.name)}">${rows}</div><div class="election-total"><span>Totalt</span><strong>${result.totalSeats}</strong></div><a class="source" href="${esc(result.source)}" target="_blank" rel="noopener">Se valgresultatet hos valgresultat.no ↗</a></section>`;
}

async function start(){
 const [municipalities,geo,polls,elections,population]=await Promise.all(['municipalities.json','norway.geojson','polls.json','elections-2023.json','population.json'].map(async f=>{const r=await fetch('data/'+f+(f==='polls.json'?'?v=poll-mandates-2':f==='municipalities.json'?'?v=municipality-names-1':f==='elections-2023.json'?'?v=election-audit-20261006':''));if(!r.ok)throw new Error('Data kunne ikke lastes');return r.json()}));
 const byId=new Map(municipalities.map(m=>[m.id,m]));const layers=new Map(),markers=new Map();const requested=new URLSearchParams(location.search).get('kommune');let selected=byId.has(requested)?requested:'4601';const select=document.querySelector('#municipality');const countySelect=document.querySelector('#county');const counties=[...new Map(municipalities.map(m=>[m.countyCode,m.countyName])).entries()].sort((a,b)=>a[1].localeCompare(b[1],'nb'));countySelect.innerHTML='<option value="">Alle fylker</option>'+counties.map(([code,name])=>`<option value="${code}">${esc(name)}</option>`).join('');function populateMunicipalities(county=''){const list=municipalities.filter(m=>!county||m.countyCode===county).slice().sort((a,b)=>a.name.localeCompare(b.name,'nb'));select.innerHTML=list.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('');if(list.some(m=>m.id===selected))select.value=selected;return list;};populateMunicipalities();
function show(id){const m=byId.get(id);if(!m)return;renderCandidates(m);selected=id;select.value=id;countySelect.value=m.countyCode;document.querySelector('#bergen-candidates').hidden=!priorityCandidates[id];const p=parties[m.party],poll=polls[id];for(const [key,l]of layers){const visible=activeParties.has(byId.get(key).party);l.setStyle({color:visible?(key===id?'#087c83':'#809aa8'):'transparent',weight:visible?(key===id?2.8:1):0,fillColor:parties[byId.get(key).party].color,fillOpacity:visible?(key===id?.30:.13):0});}for(const [key,marker]of markers){const visible=activeParties.has(byId.get(key).party);marker.setOpacity(visible?1:0);marker.getElement()?.classList.toggle('selected',key===id);}
 const previous=Dashboard.electionBaseline(elections[id],parties);
 const bars=poll?Object.entries(poll.values).map(([party,value])=>{const pp=parties[party],label=party==='H'?'Høyre':party==='R'?'Rødt':party==='V'?'Venstre':party,mandates=poll.seats?.[party]??'–',rawChange=previous[party]==null||party==='Andre'?null:Math.round((value-previous[party])*10)/10,change=rawChange==null?'–':`${rawChange>0?'+':''}${pct(Math.abs(rawChange)<0.05?0:rawChange)}`;return `<div class="bar-row" aria-label="${esc(pp.name)}: ${pct(value)} prosent, endring ${change} prosentpoeng, ${mandates} mandater"><span class="bar-label">${label}</span><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="--party:${pp.color};--value:${value/Math.max(...Object.values(poll.values))*100}%"></div></div><span class="bar-value">${pct(value)}</span><span class="bar-previous">${previous[party]==null?'–':pct(previous[party])}</span><span class="bar-change ${rawChange>0?'change-up':rawChange<0?'change-down':''}">${rawChange>0?'↑ ':rawChange<0?'↓ ':''}${change}</span><span class="bar-seats" title="${mandates} mandater">${mandates}</span></div>`}).join(''):'';
 const pollTotal=poll?Object.values(poll.seats||{}).reduce((sum,seats)=>sum+Number(seats||0),0):0;
 const pollContent=poll?`<div class="poll-head"><h3>Siste kommunemåling</h3></div><div class="chart" role="group" aria-label="Partienes oppslutning, endring siden valgresultatet i 2023 og mandater"><div class="poll-table-head" aria-hidden="true"><span>Parti</span><span></span><span>Prosent</span><span class="bar-previous">2023</span><span class="bar-change">Endring</span><span>Mandater</span></div>${bars}</div><div class="poll-total"><a class="poll-source" href="${esc(poll.source)}" target="_blank" rel="noopener">Se målingen hos Poll of polls ↗</a><span>Totalt</span><strong>${pollTotal}</strong></div><div class="poll-meta">${date(poll.date)} · ${esc(poll.client)}</div><p class="comparison-note">Endring i prosentpoeng. «–»: manglende sammenlignbart resultat eller ulik gruppering av «Andre».</p>`:`<div class="empty"><div class="empty-symbol" aria-hidden="true">▂ ▅ ▃</div><h3>Ingen måling registrert i 2026</h3><p>Vi fant ingen kommunemåling fra 2026 for ${esc(m.name)} hos Poll of polls ved siste kontroll.</p><a href="https://www.pollofpolls.no/?cmd=Maling&filter=kommune" target="_blank" rel="noopener">Se alle kommunemålinger ↗</a></div>`;
 const unusualMayorParty=mayorPartyNames[m.id]?`<small class="mayor-party-name">${esc(mayorPartyNames[m.id])}</small>`:'';
 document.querySelector('#detail-content').innerHTML=`<div class="municipality-summary"><h2>${esc(m.name)}</h2><div class="mayor"><div class="mayor-logo">${logo(p)}</div><div><small>${m.acting?'Fungerende ordfører':'Ordfører'}</small><p><strong>${esc(m.mayor)}</strong></p>${unusualMayorParty}</div></div>${m.note?`<p class="mayor-note">${esc(m.note)}</p>`:''}</div><div class="detail-data-grid"><section class="poll-panel" aria-label="Siste kommunemåling">${pollContent}</section>${renderElection(elections[id])}</div>`;Dashboard.municipal(m,elections[id],poll,parties,population);}
 const map=L.map('map',{zoomControl:false,scrollWheelZoom:!window.matchMedia('(pointer:coarse)').matches,minZoom:3,maxZoom:12,zoomSnap:.25});L.control.zoom({position:'topright'}).addTo(map);Dashboard.setMap(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);
 const filterKeys=['R','SV','Ap','MDG','Sp','V','KrF','H','FrP'];const activeParties=new Set(filterKeys);const filterHost=document.querySelector('#party-filter');filterHost.innerHTML=filterKeys.map(k=>`<button type="button" data-party-filter="${k}" aria-label="Skjul ${esc(parties[k].name)}" title="${esc(parties[k].name)}">${logo(parties[k],k)}</button>`).join('');const allButton=document.createElement('button');allButton.type='button';allButton.className='filter-all';allButton.textContent='Alle';allButton.setAttribute('aria-label','Vis alle partier');allButton.setAttribute('aria-pressed','true');filterHost.prepend(allButton);allButton.addEventListener('click',()=>{filterKeys.forEach(k=>activeParties.add(k));filterHost.querySelectorAll('button[data-party-filter]').forEach(b=>{b.classList.remove('is-off');b.setAttribute('aria-label','Skjul '+parties[b.dataset.partyFilter].name);b.setAttribute('aria-pressed','true')});allButton.setAttribute('aria-pressed','true');show(selected)});filterHost.querySelectorAll('button[data-party-filter]').forEach(b=>b.setAttribute('aria-pressed','true'));filterHost.addEventListener('click',event=>{const button=event.target.closest('button[data-party-filter]');if(!button)return;const key=button.dataset.partyFilter;if(activeParties.has(key))activeParties.delete(key);else activeParties.add(key);button.classList.toggle('is-off',!activeParties.has(key));button.setAttribute('aria-pressed',String(activeParties.has(key)));allButton.setAttribute('aria-pressed',String(activeParties.size===filterKeys.length));button.setAttribute('aria-label',`${activeParties.has(key)?'Skjul':'Vis'} ${parties[key].name}`);show(selected)});
 const boundary=L.geoJSON(geo,{style:f=>({color:'#809aa8',weight:1,fillColor:parties[byId.get(f.properties.kommunenummer).party].color,fillOpacity:.13}),onEachFeature:(feature,layer)=>{const id=feature.properties.kommunenummer,m=byId.get(id);layers.set(id,layer);layer.bindTooltip(`<strong>${esc(m.name)}</strong>${esc(m.mayor)} ${partyTooltip(m)}`,{sticky:true,direction:'top'});layer.on({click:()=>show(id)})}}).addTo(map);
 const bounds=boundary.getBounds();const countyBounds=new Map();boundary.eachLayer(layer=>{const code=String(layer.feature.properties.kommunenummer).slice(0,2);const current=countyBounds.get(code);countyBounds.set(code,current?current.extend(layer.getBounds()):layer.getBounds())});function fit(){map.fitBounds(bounds,{padding:[24,25],animate:false})}function fitSouth(){map.fitBounds([[57.2,1.0],[64.2,15.0]],{padding:[24,25],animate:false});map.setZoom(Math.min(map.getZoom()+1,9),{animate:false})}function fitCounty(code){const county=countyBounds.get(code);if(county)map.fitBounds(county,{padding:[24,25],animate:false});else fit()}fitSouth();for(const m of municipalities){const p=parties[m.party];const marker=L.marker([m.point[1],m.point[0]],{icon:L.divIcon({className:'party-marker',html:`<span class="marker-inner">${logo(p)}</span>`,iconSize:[30,30],iconAnchor:[15,15]}),title:`${m.name}: ${m.mayor} ${partyTooltip(m)}`,alt:`${m.name}: ${m.mayor} ${partyTooltip(m)}`,keyboard:true,riseOnHover:true}).addTo(map);marker.bindTooltip(`<strong>${esc(m.name)}</strong>${esc(m.mayor)} ${partyTooltip(m)}`,{direction:'top',offset:[0,-13]});marker.on({click:()=>{show(m.id);focusMunicipality(m.id)}});markers.set(m.id,marker)}function focusMunicipality(id){const point=byId.get(id)?.point;if(point)map.setView([point[1],point[0]],8.5,{animate:false})}select.addEventListener('change',()=>{show(select.value);focusMunicipality(select.value)});countySelect.addEventListener('change',()=>{const code=countySelect.value;const list=populateMunicipalities(code);if(list.length){show(list[0].id);fitCounty(code)}});new ResizeObserver(()=>map.invalidateSize()).observe(document.querySelector('.map-shell'));show(selected);
}
start().catch(error=>{console.error(error);document.querySelector('#map-error').hidden=false;document.querySelector('#map-error').textContent='Kartet kunne ikke lastes. Prøv å laste siden på nytt.';document.querySelector('#detail-content').innerHTML='<p>Kommuneinformasjonen kunne ikke lastes. Prøv igjen om litt.</p>'});
